def limit_arg(value: str) -> int:
    """argparse 类型：--limit 的数量参数，仅接受严格的正整数。

    与 int(value) 不同，这里不接受带空白、正负号、小数点或下划线的
    写法（如 " 2"、"+2"、"2.0"、"1_0"），空值、零与负数同样拒绝，
    使数量参数的合法形式唯一确定。
    """
    if not value or not value.isdigit() or int(value) < 1:
        raise argparse.ArgumentTypeError(
            f"数量参数必须是正整数: {value!r}"
        )
    return int(value)

